/// <summary>
/// Controller class for Update slot area batch job
/// </summary>
class METUpdateSlotAreaController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Specifies if the batch task is retryable for exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// New method
/// </summary>
protected void new()
{
    super(classStr(METUpdateSlotAreaService), methodStr(METUpdateSlotAreaService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "Update Slot area";
}

/// <summary>
/// Executes the batch job.
/// </summary>
/// <param name = "_args">
/// <c>Args</c>.
/// </param>
public static void main(Args _args)
{
    METUpdateSlotAreaController controller = new METUpdateSlotAreaController();
    controller.parmArgs(_args);
    //controller.initContract();
    controller.startOperation();
}
